const T = (p: [string, string]) => tr(p[0], p[1]);

export function NewsPanel() {
  return (
    <div className="news">
      {NOTES.map((n) => (
        <article key={n.date} className="news-entry">
          <h4>
            <span className="news-date">{n.date}</span> {T(n.title)}
          </h4>
          <ul>
            {n.items.map((it, i) => (
              <li key={i}>{T(it)}</li>
            ))}
          </ul>
        </article>
      ))}
    </div>
  );
}

