export function GuidePanel() {
  const [open, setOpen] = useState(0);
  return (
    <div className="news guide">
      {GUIDE.map((g, i) => (
        <details key={i} open={open === i} onToggle={(e) => (e.currentTarget as HTMLDetailsElement).open && setOpen(i)}>
          <summary>{T(g.title)}</summary>
          <ul>
            {g.text.map((p, k) => (
              <li key={k}>{T(p)}</li>
            ))}
          </ul>
        </details>
      ))}
    </div>
  );
}
